(3684173, 515351, 6999, '<td valign="top">He''s a happy looking little fella'', no? Perhaps a pity you couldn''t have resolved a little more detail, or hadn''t lost so much in processing, whatever''s caused it.</td>', 'He''s a happy looking little fella'', no? Perhaps a pity you couldn''t have resolved a little more detail, or hadn''t lost so much in processing, whatever''s caused it.', '2007-05-23 04:55:25.000000', NULL, 1),
(3684175, 515137, 6999, '<td valign="top">Nice weird moment - gets better the more one looks at it, too.</td>', 'Nice weird moment - gets better the more one looks at it, too.', '2007-05-23 04:57:11.000000', NULL, 1),
(3684188, 517550, 67671, '<td valign="top">better if the sword was not cropped of at the top</td>', 'better if the sword was not cropped of at the top', '2007-05-23 05:25:58.000000', NULL, 1),
(3684194, 518738, 48560, '<td valign="top">that tip of the sword looked almost like the knight''s nose!</td>', 'that tip of the sword looked almost like the knight''s nose!', '2007-05-23 05:32:51.000000', NULL, 1),
