(3690742, 518515, 43410, '<td valign="top">5</td>', '5', '2007-05-24 12:29:53.000000', NULL, 1),
(3690759, 517780, 43410, '<td valign="top">i remember this guy from the langdon''s birthday challenge.  too cute.</td>', 'i remember this guy from the langdon''s birthday challenge.  too cute.', '2007-05-24 12:33:52.000000', NULL, 1),
(3690812, 518178, 62554, '<td valign="top">Nice angle and DoF</td>', 'Nice angle and DoF', '2007-05-24 12:44:49.000000', NULL, 1),
(3690822, 517359, 62554, '<td valign="top">very effective - and simple too</td>', 'very effective - and simple too', '2007-05-24 12:47:11.000000', NULL, 1),
(3690836, 519011, 61961, '<td valign="top">Definitely meets the challenge theme, but as I said in our team thread, you''ve now entered the dangerous world of floral photography.  Why not just jump out of an airplane if you wanted a risky undertaking? :-)<br/> <br/>I like your composition very much, and I think you did well to blur the background.  Was this done with a Macro setting?  To be effective I think this needs to be sharper, either with the entire rose in focus, or with a clearly identifiable difference, like "This part of the flower is the focal point, and this part is meant to be blurry."  Generally the focal point should be the part the most interesting or important part.  In most flowers that would include the pistil and/or stamen.  For a rose, I guess it would be the center.  Having never taken flower photos myself, I''m sort of talking through my -uhm- hat.<br/> <br/>Not bad for a first entry, I can''t wait to see what you come up with for week two. :-D</td>', 'Definitely meets the challenge theme, but as I said in our team thread, you''ve now entered the dangerous world of floral photography.  Why not just jump out of an airplane if you wanted a risky undertaking? :-) I like your composition very much, and I think you did well to blur the background.  Was this done with a Macro setting?  To be effective I think this needs to be sharper, either with the entire rose in focus, or with a clearly identifiable difference, like "This part of the flower is the focal point, and this part is meant to be blurry."  Generally the focal point should be the part the most interesting or important part.  In most flowers that would include the pistil and/or stamen.  For a rose, I guess it would be the center.  Having never taken flower photos myself, I''m sort of talking through my -uhm- hat. Not bad for a first entry, I can''t wait to see what you come up with for week two. :-D', '2007-05-24 12:52:00.000000', NULL, 1),
(3690844, 517808, 78488, '<td valign="top">beautiful picture, excellent calirty and composition. 10 + favorites</td>', 'beautiful picture, excellent calirty and composition. 10 + favorites', '2007-05-24 12:54:15.000000', NULL, 1),
