INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(3700292, 518732, 30982, '<td valign="top">I quite like the angle and the focus on his very interesting face!</td>', 'I quite like the angle and the focus on his very interesting face!', '2007-05-27 13:17:44.000000', NULL, 1),
(3700298, 517359, 30982, '<td valign="top">I like your interpretation of the name.</td>', 'I like your interpretation of the name.', '2007-05-27 13:20:24.000000', NULL, 1),
(3700315, 517358, 30982, '<td valign="top">I like the strange mystery of this - what are these things?  Where are they?  Why are they lit up with no one there?  Aptly chosen username.</td>', 'I like the strange mystery of this - what are these things?  Where are they?  Why are they lit up with no one there?  Aptly chosen username.', '2007-05-27 13:28:49.000000', NULL, 1),
(3700326, 516298, 1031, '<td valign="top">Great combination of sharp detail, motion blur, and compatible bokeh. I''d like to see what it would look like with the bird on the right, flying into the frame, though flying out probably fits the title/theme better.</td>', 'Great combination of sharp detail, motion blur, and compatible bokeh. I''d like to see what it would look like with the bird on the right, flying into the frame, though flying out probably fits the title/theme better.', '2007-05-27 13:33:37.000000', NULL, 1),
(3700334, 518873, 1031, '<td valign="top">I think I would process this with higher contrast effect, to make it look sunnier; as it is, it seems a little overcast and drearier than need be. I''d maybe try and get the sky bluer as well, typically using Curves (in Photoshop).</td>', 'I think I would process this with higher contrast effect, to make it look sunnier; as it is, it seems a little overcast and drearier than need be. I''d maybe try and get the sky bluer as well, typically using Curves (in Photoshop).', '2007-05-27 13:37:29.000000', NULL, 1),
(3700344, 518207, 1031, '<td valign="top">I haven''t "decided" yet if I really like the whole blurry waterfall look (rather than a stop-action look), but this is a nice example of it. I like that it retains some of the detail/texture in the water. I''d also probably boost the contrast a bit.</td>', 'I haven''t "decided" yet if I really like the whole blurry waterfall look (rather than a stop-action look), but this is a nice example of it. I like that it retains some of the detail/texture in the water. I''d also probably boost the contrast a bit.', '2007-05-27 13:44:34.000000', NULL, 1),
(3700351, 514442, 1031, '<td valign="top">Interesting and rather compelling post-processing effect; nice work.</td>', 'Interesting and rather compelling post-processing effect; nice work.', '2007-05-27 13:48:00.000000', NULL, 1),
(3700358, 518697, 1031, '<td valign="top">Nice steam effect/capture.</td>', 'Nice steam effect/capture.', '2007-05-27 13:49:41.000000', NULL, 1),
