(3705469, 518081, 76062, '<td valign="top">Hee.  Well done,</td>', 'Hee.  Well done,', '2007-05-28 17:22:44.000000', NULL, 1),
(3705474, 518978, 76062, '<td valign="top">Colorful. I like the different reactions to being photographed.</td>', 'Colorful. I like the different reactions to being photographed.', '2007-05-28 17:24:26.000000', NULL, 1),
(3705478, 517188, 76062, '<td valign="top">Wow.  Very nice capture.</td>', 'Wow.  Very nice capture.', '2007-05-28 17:25:13.000000', NULL, 1),
(3705481, 517405, 76062, '<td valign="top">Cute.</td>', 'Cute.', '2007-05-28 17:26:06.000000', NULL, 1),
(3705485, 517708, 76062, '<td valign="top">Captures the theme pretty well -- the pony seems to be keeping its eye on the camera.</td>', 'Captures the theme pretty well -- the pony seems to be keeping its eye on the camera.', '2007-05-28 17:27:22.000000', NULL, 1),
(3705487, 518781, 76062, '<td valign="top">Very nice.</td>', 'Very nice.', '2007-05-28 17:27:45.000000', NULL, 1),
(3705489, 518603, 2553, '<td valign="top">I just love this image!  It is adorable, even though the topknot on that poor baby is cut back so far from the eyes that it almost looks like a mohawk cut.  Maybe that''s part of what makes it so cute. He/she actually looks a bit put out with being an angel. You''ll probably get a lot of "blown-out highlights" comments, but it makes no difference to me, this is one of my favorites in the challenge.  I wish people would just get over all the technical nit-picking and just enjoy the images.  Good pick for this challenge, and well done!</td>', 'I just love this image!  It is adorable, even though the topknot on that poor baby is cut back so far from the eyes that it almost looks like a mohawk cut.  Maybe that''s part of what makes it so cute. He/she actually looks a bit put out with being an angel. You''ll probably get a lot of "blown-out highlights" comments, but it makes no difference to me, this is one of my favorites in the challenge.  I wish people would just get over all the technical nit-picking and just enjoy the images.  Good pick for this challenge, and well done!', '2007-05-28 17:28:10.000000', NULL, 1),
(3705490, 518828, 2553, '<td valign="top">To say this is beautiful would be understating it!  Lovely and eye-catching composition.  A very nice piece of work.</td>', 'To say this is beautiful would be understating it!  Lovely and eye-catching composition.  A very nice piece of work.', '2007-05-28 17:28:14.000000', NULL, 1),
(3705491, 519025, 76062, '<td valign="top">Cute.</td>', 'Cute.', '2007-05-28 17:28:24.000000', NULL, 1),
(3705493, 515704, 2553, '<td valign="top">A lovely image and one of my favorites in the challenge.</td>', 'A lovely image and one of my favorites in the challenge.', '2007-05-28 17:29:14.000000', NULL, 1),
(3705494, 517561, 2553, '<td valign="top">How did you get such a shot?  This is adorable, and wow, your lighting was almost perfect wasn''t it?  Great execution of your concept.</td>', 'How did you get such a shot?  This is adorable, and wow, your lighting was almost perfect wasn''t it?  Great execution of your concept.', '2007-05-28 17:29:20.000000', NULL, 1),
(3705499, 514705, 2553, '<td valign="top">Wow, the contrast in the colors here really makes this image lovely.  I love the "flow" of the wheat, and the gorgeous blue against the warm tones of the background.  Wonderful job with this, one of my favorites in the challenge.</td>', 'Wow, the contrast in the colors here really makes this image lovely.  I love the "flow" of the wheat, and the gorgeous blue against the warm tones of the background.  Wonderful job with this, one of my favorites in the challenge.', '2007-05-28 17:31:18.000000', NULL, 1),
(3705531, 518662, 2553, '<td valign="top">Having just tried to shoot a heron today, I full appreciation of the beauty of this shot.  Very nicely done, and of course, perfect for the challenge.</td>', 'Having just tried to shoot a heron today, I full appreciation of the beauty of this shot.  Very nicely done, and of course, perfect for the challenge.', '2007-05-28 17:38:35.000000', NULL, 1),
(3705532, 517501, 2553, '<td valign="top">That''s quite a piece of artwork there. An interesting image, with good lighting, exposure and color.  Now that I''m back for a second look, I think I''ll have to bump this up a bit.</td>', 'That''s quite a piece of artwork there. An interesting image, with good lighting, exposure and color.  Now that I''m back for a second look, I think I''ll have to bump this up a bit.', '2007-05-28 17:38:39.000000', NULL, 1),
