(3705716, 518223, 2553, '<td valign="top">Though not an image that makes me say "WOW", it fits the challenge well, and is very nicely done.</td>', 'Though not an image that makes me say "WOW", it fits the challenge well, and is very nicely done.', '2007-05-28 18:26:02.000000', NULL, 1),
(3705717, 516584, 2553, '<td valign="top">WOW!  I cannot wait to find out where you live, or where you took this!  This bird is just amazing.  The colors are gorgeous.  Nice concept for the username, and nice image.</td>', 'WOW!  I cannot wait to find out where you live, or where you took this!  This bird is just amazing.  The colors are gorgeous.  Nice concept for the username, and nice image.', '2007-05-28 18:26:05.000000', NULL, 1),
(3705718, 516298, 2553, '<td valign="top">This bird is adorable.  The position of the bird relative to the viewer feels a bit awkward to me, nevertheless, it fits the challenge title you''ve selected perfectly.</td>', 'This bird is adorable.  The position of the bird relative to the viewer feels a bit awkward to me, nevertheless, it fits the challenge title you''ve selected perfectly.', '2007-05-28 18:26:10.000000', NULL, 1),
(3705719, 513439, 2553, '<td valign="top">Ahhh...I really enjoy this image.  I like the jumble of all the colors against the dark background, and the silhouette of the person seems to fit into it perfectly as though meant to be a part of the surroundings.  I believe that I would have cropped off a small bit of the left side, up to the edge of that dark blob, that dark area doesn''t really add anything to the image, and I think it would help with balance a bit.</td>', 'Ahhh...I really enjoy this image.  I like the jumble of all the colors against the dark background, and the silhouette of the person seems to fit into it perfectly as though meant to be a part of the surroundings.  I believe that I would have cropped off a small bit of the left side, up to the edge of that dark blob, that dark area doesn''t really add anything to the image, and I think it would help with balance a bit.', '2007-05-28 18:26:13.000000', NULL, 1),
(3705723, 518392, 2553, '<td valign="top">An absolutely beautiful image.  I''m not really "into" flower shots, but this is quite lovely.  Perfect for your challenge title of course!</td>', 'An absolutely beautiful image.  I''m not really "into" flower shots, but this is quite lovely.  Perfect for your challenge title of course!', '2007-05-28 18:26:17.000000', NULL, 1),
(3705733, 517816, 2553, '<td valign="top">Suits the challenge well, but otherwise does not have a lot of impact for me.</td>', 'Suits the challenge well, but otherwise does not have a lot of impact for me.', '2007-05-28 18:27:50.000000', NULL, 1),
(3705774, 518603, 10818, '<td valign="top">HeHe...that is funny, and really well done.  But if he bites you for dressing him like that, I really cant blame him.  :)</td>', 'HeHe...that is funny, and really well done.  But if he bites you for dressing him like that, I really cant blame him.  :)', '2007-05-28 18:36:51.000000', NULL, 1),
