(3705959, 517487, 27556, '<td valign="top">This looks like a post card to me very picture esque.</td>', 'This looks like a post card to me very picture esque.', '2007-05-28 19:23:52.000000', NULL, 1),
(3705963, 517780, 27556, '<td valign="top">Bonus point for having a image that makes me laugh when it appears on my screen. Nice capture, and composition. He looks like hes trying to meditate. There is also a nice amount of detail in the fur as well. Nice job</td>', 'Bonus point for having a image that makes me laugh when it appears on my screen. Nice capture, and composition. He looks like hes trying to meditate. There is also a nice amount of detail in the fur as well. Nice job', '2007-05-28 19:25:04.000000', NULL, 1),
(3705968, 517367, 27556, '<td valign="top">Very stunning comopsition, and I love to choice to make it b&amp;w. Possible a little more of a crop on the bottom there is a circular shape on the bottom that I find distracting.</td>', 'Very stunning comopsition, and I love to choice to make it b&w. Possible a little more of a crop on the bottom there is a circular shape on the bottom that I find distracting.', '2007-05-28 19:26:18.000000', NULL, 1),
(3705970, 518303, 27556, '<td valign="top">To go with the title I would crop tighted on the bucket. I do like the choice of b&amp;w with this image though</td>', 'To go with the title I would crop tighted on the bucket. I do like the choice of b&w with this image though', '2007-05-28 19:27:07.000000', NULL, 1),
(3705972, 518828, 27556, '<td valign="top">very picture esque, almost a painting. I wonder if a slightly tighter crop would help this image at all, and give it a tighter subject</td>', 'very picture esque, almost a painting. I wonder if a slightly tighter crop would help this image at all, and give it a tighter subject', '2007-05-28 19:28:05.000000', NULL, 1),
(3705975, 515416, 27556, '<td valign="top">Took me a second to realize what I was looking at... but i like that. Not every shot needs to be stright forward. Its amazing how much detail there can be on an everyday object.</td>', 'Took me a second to realize what I was looking at... but i like that. Not every shot needs to be stright forward. Its amazing how much detail there can be on an everyday object.', '2007-05-28 19:28:59.000000', NULL, 1),
(3705981, 514019, 27556, '<td valign="top">Nice capture, I know it couldnt be helped in this image but to my eye I find the green tree very distracting since the cammel is the same color as the sand the tree is standing out more than the cammel which i dont think was the intent.</td>', 'Nice capture, I know it couldnt be helped in this image but to my eye I find the green tree very distracting since the cammel is the same color as the sand the tree is standing out more than the cammel which i dont think was the intent.', '2007-05-28 19:30:30.000000', NULL, 1),
(3705982, 518507, 27556, '<td valign="top">To me this is an average landscap type shot. It would benifit from a little bit of post processing, and the composition should be more focused on one area of the plant.</td>', 'To me this is an average landscap type shot. It would benifit from a little bit of post processing, and the composition should be more focused on one area of the plant.', '2007-05-28 19:31:24.000000', NULL, 1),
