(3708396, 518114, 76430, '<td valign="top">Very nice idea and execution, but it''s very grainy.  You must have used high ISO and used flames alone for lighting.  I think having an additional fill light would have helped tremendously.</td>', 'Very nice idea and execution, but it''s very grainy.  You must have used high ISO and used flames alone for lighting.  I think having an additional fill light would have helped tremendously.', '2007-05-29 12:11:19.000000', NULL, 1),
(3708408, 518732, 76430, '<td valign="top">Wow, that is shallow depth of field!  I''d like to see the entire grasshopper in focus.  Maybe back away and zoom or crop or higher F stop?  Excellent sharpness on the head though.</td>', 'Wow, that is shallow depth of field!  I''d like to see the entire grasshopper in focus.  Maybe back away and zoom or crop or higher F stop?  Excellent sharpness on the head though.', '2007-05-29 12:14:53.000000', NULL, 1),
(3708409, 518634, 42495, '<td valign="top">Statues tend not to score well, but I like this one.  The yellow on the right is a bit distracting.</td>', 'Statues tend not to score well, but I like this one.  The yellow on the right is a bit distracting.', '2007-05-29 12:14:59.000000', NULL, 1),
(3708417, 516084, 76430, '<td valign="top">Beautiful scene and nice frame, but I don''t think this pictures the username well.</td>', 'Beautiful scene and nice frame, but I don''t think this pictures the username well.', '2007-05-29 12:19:30.000000', NULL, 1),
(3708450, 515263, 76430, '<td valign="top">The lighting gives away the trick (the little person is in sunlight like the ground in background), but good effect.  I think the feet are cut off too.</td>', 'The lighting gives away the trick (the little person is in sunlight like the ground in background), but good effect.  I think the feet are cut off too.', '2007-05-29 12:28:05.000000', NULL, 1),
